import SwiftUI

/// A live figure generated by the backend's symbolic engine.
///
/// The client draws whatever the payload describes - a sampled curve, a part-whole
/// bar model, or a set of marked points - and contains no formula of its own. That is
/// the point: a concept nobody hand-authored still gets a working, parameterised
/// figure, and moving a slider re-asks the engine rather than re-implementing the
/// mathematics here. Nothing in the payload is executable, so a generated expression
/// can never run code on the machine.
struct SimulationLab: View {
    let conceptID: String
    @ObservedObject var store: AppStore
    var compact = false

    @State private var payload: JSON = .null
    @State private var values: [String: Double] = [:]
    @State private var failure: String?

    /// Changing this restarts the fetch task, which is how a slider drag becomes a
    /// request. The short delay at the top of ``fetch`` means a drag in progress
    /// cancels its own predecessors instead of queueing a request per frame.
    private var requestKey: String {
        conceptID + "|" + values.keys.sorted().map { "\($0)=\(values[$0] ?? 0)" }.joined(separator: ",")
    }

    var body: some View {
        VStack(alignment: .leading, spacing: 12) {
            if let failure {
                Label(failure, systemImage: "exclamationmark.triangle")
                    .font(.system(size: 11)).foregroundStyle(Palette.secondary)
            } else if payload.isNull {
                HStack(spacing: 8) {
                    ProgressView().controlSize(.small)
                    Text("Generating a figure for this concept…").font(.system(size: 11))
                        .foregroundStyle(Palette.secondary)
                }.frame(height: 60)
            } else {
                content
            }
        }
        .task(id: requestKey) { await fetch() }
        .accessibilityIdentifier("generated.simulation")
    }

    private var content: some View {
        VStack(alignment: .leading, spacing: 12) {
            if !payload["objective"].string.isEmpty {
                Text(payload["objective"].string).font(.system(size: 11))
                    .foregroundStyle(Palette.secondary).lineSpacing(3)
                    .fixedSize(horizontal: false, vertical: true)
            }
            GeneratedFigure(payload: payload).frame(height: compact ? 180 : 235)
            expressionLine
            if !payload["readouts"].array.isEmpty { readouts }
            if !parameters.isEmpty { sliders }
            if !payload["steps"].array.isEmpty { steps }
            if !payload["table"].array.isEmpty && !compact { probeTable }
            notes
        }
    }

    private var expressionLine: some View {
        VStack(alignment: .leading, spacing: 4) {
            Text(payload["expression"]["substituted"].string)
                .font(.system(size: 15, weight: .medium, design: .serif))
                .textSelection(.enabled)
            if !payload["secondary"]["expression"].string.isEmpty {
                Text("and  " + payload["secondary"]["expression"].string)
                    .font(.system(size: 15, weight: .medium, design: .serif))
                    .foregroundStyle(Palette.forest.opacity(0.8)).textSelection(.enabled)
            }
            if !payload["expression"]["source"].string.isEmpty &&
                payload["expression"]["source"].string != payload["expression"]["substituted"].string {
                Text("rule: " + payload["expression"]["source"].string)
                    .font(.system(size: 10, design: .monospaced)).foregroundStyle(Palette.secondary)
            }
        }
        .padding(12).frame(maxWidth: .infinity, alignment: .leading)
        .background(Palette.sage.opacity(0.5), in: RoundedRectangle(cornerRadius: 12))
    }

    private var readouts: some View {
        LazyVGrid(columns: [GridItem(.adaptive(minimum: 130), spacing: 8)], spacing: 8) {
            ForEach(Array(payload["readouts"].array.enumerated()), id: \.offset) { _, item in
                VStack(alignment: .leading, spacing: 2) {
                    Text(item["label"].string.uppercased()).font(.system(size: 9, weight: .semibold))
                        .tracking(0.6).foregroundStyle(Palette.secondary)
                    Text(item["value"].string).font(.system(size: 13, weight: .semibold))
                    if !item["detail"].string.isEmpty {
                        Text(item["detail"].string).font(.system(size: 9))
                            .foregroundStyle(Palette.secondary).lineSpacing(2)
                            .fixedSize(horizontal: false, vertical: true)
                    }
                }
                .padding(10).frame(maxWidth: .infinity, alignment: .leading)
                .background(Palette.muted, in: RoundedRectangle(cornerRadius: 11))
            }
        }
    }

    private var parameters: [JSON] { payload["parameters"].array }

    private var sliders: some View {
        VStack(alignment: .leading, spacing: 10) {
            HStack {
                Eyebrow(text: "CHANGE ONE THING AT A TIME")
                Spacer()
                Button("Reset") { values = [:] }
                    .buttonStyle(.plain).font(.system(size: 10, weight: .medium))
                    .foregroundStyle(Palette.forest)
            }
            ForEach(parameters, id: \.self) { parameter in
                let id = parameter["id"].string
                let low = parameter["min"].double, high = parameter["max"].double
                let step = parameter["integer"].bool ? 1.0 : max((high - low) / 200, 0.0001)
                HStack(spacing: 12) {
                    Text(parameter["label"].string).font(.system(size: 11, weight: .medium))
                        .frame(width: compact ? 108 : 175, alignment: .leading)
                        .lineLimit(2).fixedSize(horizontal: false, vertical: true)
                    Slider(value: binding(id, low: low, high: high), in: low...max(high, low + 0.0001), step: step)
                        .tint(Palette.forest)
                        .accessibilityIdentifier("simulation.parameter." + id)
                    Text(display(values[id] ?? parameter["value"].double, unit: parameter["unit"].string))
                        .font(.system(size: 11, design: .monospaced))
                        .frame(width: 54, alignment: .trailing)
                }
            }
        }
    }

    private var steps: some View {
        VStack(alignment: .leading, spacing: 7) {
            Eyebrow(text: "WHY")
            ForEach(Array(payload["steps"].array.enumerated()), id: \.offset) { index, step in
                HStack(alignment: .top, spacing: 8) {
                    Text("\(index + 1)").font(.system(size: 9, weight: .semibold))
                        .foregroundStyle(Palette.forest)
                        .frame(width: 15, height: 15)
                        .background(Palette.sage, in: Circle())
                    Text(step.string).font(.system(size: 11)).lineSpacing(3)
                        .fixedSize(horizontal: false, vertical: true)
                    Spacer(minLength: 0)
                }
            }
        }
    }

    private var probeTable: some View {
        VStack(alignment: .leading, spacing: 6) {
            Eyebrow(text: "CHECK BY HAND")
            HStack {
                Text(payload["domain"]["min"].double.formatted(.number.precision(.fractionLength(0...2))))
                    .font(.system(size: 10, design: .monospaced)).foregroundStyle(Palette.secondary).frame(width: 62, alignment: .leading)
                Text("→").font(.system(size: 10)).foregroundStyle(Palette.secondary).frame(width: 18)
                Text(payload["domain"]["max"].double.formatted(.number.precision(.fractionLength(0...2))))
                    .font(.system(size: 10, design: .monospaced)).foregroundStyle(Palette.secondary)
                Spacer()
                Text("sampled at \(payload["domain"]["samples"].int) points")
                    .font(.system(size: 9)).foregroundStyle(Palette.secondary)
            }
            ForEach(Array(payload["table"].array.enumerated()), id: \.offset) { _, row in
                HStack(spacing: 0) {
                    Text("x = " + short(row["x"].double)).font(.system(size: 10, design: .monospaced)).frame(width: 78, alignment: .leading)
                    Text("y = " + short(row["y"].double)).font(.system(size: 10, design: .monospaced))
                    Spacer()
                }
                .padding(.vertical, 2)
                Divider().overlay(Palette.line)
            }
        }
    }

    private var notes: some View {
        VStack(alignment: .leading, spacing: 5) {
            ForEach(Array(payload["notes"].array.enumerated()), id: \.offset) { _, note in
                HStack(alignment: .top, spacing: 6) {
                    Image(systemName: "info.circle").font(.system(size: 9)).foregroundStyle(Palette.secondary)
                    Text(note.string).font(.system(size: 10)).foregroundStyle(Palette.secondary).lineSpacing(3)
                        .fixedSize(horizontal: false, vertical: true)
                }
            }
        }
    }

    private func binding(_ id: String, low: Double, high: Double) -> Binding<Double> {
        Binding(
            get: { min(max(values[id] ?? low, low), high) },
            set: { new in values[id] = min(max(new, low), high) }
        )
    }

    private func display(_ value: Double, unit: String) -> String {
        let text = short(value)
        return unit.isEmpty ? text : text + unit
    }

    private func short(_ value: Double) -> String {
        guard value.isFinite else { return "—" }
        if value == value.rounded() && abs(value) < 1e6 { return String(Int(value)) }
        return value.formatted(.number.precision(.significantDigits(1...4)))
    }

    private func fetch() async {
        if !values.isEmpty {
            // A drag in progress keeps cancelling its own predecessors, so only the
            // settled value issues a request.
            try? await Task.sleep(nanoseconds: 60_000_000)
            if Task.isCancelled { return }
        }
        let query = values.keys.sorted().map { URLQueryItem(name: $0, value: "\(values[$0] ?? 0)") }
        let path = "/simulations/" + (conceptID.addingPercentEncoding(withAllowedCharacters: .urlPathAllowed) ?? conceptID)
        do {
            let result = try await store.api.json(path, query: query)
            if Task.isCancelled { return }
            payload = result
            failure = nil
            if values.isEmpty {
                var seeded: [String: Double] = [:]
                for parameter in result["parameters"].array where !parameter["id"].string.isEmpty {
                    seeded[parameter["id"].string] = parameter["value"].double
                }
                values = seeded
            }
        } catch {
            if Task.isCancelled { return }
            failure = "This figure could not be generated right now. The rest of the page still works."
        }
    }
}

// MARK: - Drawing

/// Draws a payload. Nothing here decides what to draw from a formula: the payload
/// already says whether it is a curve, a bar model or a set of points.
struct GeneratedFigure: View {
    let payload: JSON

    private var isScene: Bool { payload["figure"].string == "scene" }

    var body: some View {
        Canvas { context, size in
            let inset = 26.0
            let area = CGRect(x: inset, y: inset, width: max(10, size.width - inset * 2),
                              height: max(10, size.height - inset * 2))
            let bounds = FigureBounds(payload: payload)
            drawGrid(context, area, bounds)
            if isScene {
                drawScene(context, area, bounds)
            } else {
                drawCurve(context, area, bounds)
            }
        }
        .background(Color.white.opacity(0.72), in: RoundedRectangle(cornerRadius: 14))
        .overlay(RoundedRectangle(cornerRadius: 14).strokeBorder(Palette.line, lineWidth: 1))
        .accessibilityLabel(payload["title"].string)
    }

    private func drawGrid(_ context: GraphicsContext, _ area: CGRect, _ bounds: FigureBounds) {
        var grid = Path()
        for index in 0...4 {
            let t = Double(index) / 4
            let x = area.minX + area.width * t
            let y = area.minY + area.height * t
            grid.move(to: CGPoint(x: x, y: area.minY)); grid.addLine(to: CGPoint(x: x, y: area.maxY))
            grid.move(to: CGPoint(x: area.minX, y: y)); grid.addLine(to: CGPoint(x: area.maxX, y: y))
        }
        context.stroke(grid, with: .color(Palette.line), lineWidth: 1)

        // Axes are drawn only where zero is actually inside the window, so the
        // picture never claims an axis that is off-screen.
        var axes = Path()
        if bounds.minY <= 0 && bounds.maxY >= 0 {
            let y = bounds.screenY(0, area)
            axes.move(to: CGPoint(x: area.minX, y: y)); axes.addLine(to: CGPoint(x: area.maxX, y: y))
        }
        if bounds.minX <= 0 && bounds.maxX >= 0 {
            let x = bounds.screenX(0, area)
            axes.move(to: CGPoint(x: x, y: area.minY)); axes.addLine(to: CGPoint(x: x, y: area.maxY))
        }
        context.stroke(axes, with: .color(Palette.secondary.opacity(0.45)), lineWidth: 1)
    }

    private func drawCurve(_ context: GraphicsContext, _ area: CGRect, _ bounds: FigureBounds) {
        for series in [payload["series"].array, payload["secondary"]["series"].array] where !series.isEmpty {
            let secondary = series == payload["secondary"]["series"].array
            var path = Path()
            var pen = false
            for point in series {
                guard let x = point.array.first?.optionalDouble, let y = point.array.count > 1 ? point.array[1].optionalDouble : nil else {
                    pen = false
                    continue
                }
                let location = CGPoint(x: bounds.screenX(x, area), y: bounds.screenY(y, area))
                if pen { path.addLine(to: location) } else { path.move(to: location); pen = true }
            }
            context.stroke(path, with: .color(secondary ? Palette.forest.opacity(0.45) : Palette.forest),
                           style: StrokeStyle(lineWidth: secondary ? 1.5 : 2.2, dash: secondary ? [5, 4] : []))
        }

        // Roots and turning points are marked from the payload's own features, not
        // recomputed here.
        for root in payload["features"]["roots"].array {
            guard let value = root.optionalDouble else { continue }
            mark(context, CGPoint(x: bounds.screenX(value, area), y: bounds.screenY(0, area)),
                 radius: 3.6, fill: Palette.peach, stroke: Palette.forest)
        }
        for extremum in payload["features"]["extrema"].array {
            guard let x = extremum["x"].optionalDouble, let y = extremum["y"].optionalDouble else { continue }
            mark(context, CGPoint(x: bounds.screenX(x, area), y: bounds.screenY(y, area)),
                 radius: 4, fill: Palette.lavender, stroke: Palette.forest)
        }
        if let probe = payload["probe"].object["x"]?.optionalDouble, let value = payload["probe"].object["y"]?.optionalDouble,
           value.isFinite {
            let location = CGPoint(x: bounds.screenX(probe, area), y: bounds.screenY(value, area))
            var ring = Path(); ring.addEllipse(in: CGRect(x: location.x - 7, y: location.y - 7, width: 14, height: 14))
            context.stroke(ring, with: .color(Palette.forest.opacity(0.5)), lineWidth: 1.5)
            mark(context, location, radius: 4.2, fill: Palette.forest, stroke: .white)
        }
    }

    private func drawScene(_ context: GraphicsContext, _ area: CGRect, _ bounds: FigureBounds) {
        let bars = payload["parts"].array
        for (row, part) in bars.enumerated() {
            let cells = max(1, part["denominator"].int)
            let shaded = max(0, part["shaded"].int)
            let rowHeight = min(30, area.height / Double(max(bars.count, 1)) * 0.55)
            let gap = area.height / Double(max(bars.count, 1))
            let top = area.minY + gap * Double(row) + (gap - rowHeight) / 2
            let full = Double(cells)
            // A total larger than one whole is shown as whole units plus the remainder,
            // so 53/35 does not silently draw as a single overflowing bar.
            let whole = shaded / cells
            let remainder = shaded % cells
            let segments = whole + (remainder > 0 ? 1 : 0)
            let segmentWidth = area.width / Double(max(segments, 1))
            for segment in 0..<max(segments, 1) {
                let filled = segment < whole ? cells : remainder
                for cell in 0..<cells {
                    let rect = CGRect(x: area.minX + segmentWidth * Double(segment) + segmentWidth * Double(cell) / full,
                                      y: top, width: max(1, segmentWidth / full), height: rowHeight)
                    let colour = cell < filled ? partColor(part["colour"].string) : partColor(part["colour"].string).opacity(0.16)
                    context.fill(Path(rect), with: .color(colour))
                    if cells <= 60 { context.stroke(Path(rect), with: .color(.white), lineWidth: 1) }
                }
            }
            let label = part["label"].string
            context.draw(Text(label).font(.system(size: 11, weight: .semibold, design: .serif)).foregroundColor(Palette.ink),
                         at: CGPoint(x: area.minX + 18, y: top - 9), anchor: .leading)
        }
        for markItem in payload["marks"].array {
            guard let x = markItem["x"].optionalDouble, let y = markItem["y"].optionalDouble else { continue }
            let location = CGPoint(x: bounds.screenX(x, area), y: bounds.screenY(y, area))
            mark(context, location, radius: 4.5, fill: partColor(markItem["colour"].string), stroke: .white)
            let label = markItem["label"].string
            if !label.isEmpty {
                context.draw(Text(label).font(.system(size: 9)).foregroundColor(Palette.secondary),
                             at: CGPoint(x: location.x + 8, y: location.y - 9), anchor: .leading)
            }
        }
    }

    private func mark(_ context: GraphicsContext, _ point: CGPoint, radius: Double, fill: Color, stroke: Color) {
        let rect = CGRect(x: point.x - radius, y: point.y - radius, width: radius * 2, height: radius * 2)
        var path = Path(); path.addEllipse(in: rect)
        context.fill(path, with: .color(fill))
        context.stroke(path, with: .color(stroke), lineWidth: 1.4)
    }

    private func partColor(_ name: String) -> Color {
        switch name {
        case "secondary": return Palette.lavender
        case "accent": return Palette.peach
        default: return Palette.forest
        }
    }
}

/// Maps data coordinates onto the drawing area. The window is taken from the payload,
/// so a figure is never rescaled by a constant the client guessed.
struct FigureBounds {
    var minX = -6.0, maxX = 6.0, minY = -6.0, maxY = 6.0

    init(payload: JSON) {
        var xs: [Double] = [], ys: [Double] = []
        for series in [payload["series"].array, payload["secondary"]["series"].array] {
            for point in series {
                guard let x = point.array.first?.optionalDouble,
                      let y = point.array.count > 1 ? point.array[1].optionalDouble : nil else { continue }
                xs.append(x); ys.append(y)
            }
        }
        for item in payload["marks"].array {
            if let x = item["x"].optionalDouble { xs.append(x) }
            if let y = item["y"].optionalDouble { ys.append(y) }
        }
        for root in payload["features"]["roots"].array {
            if let value = root.optionalDouble { xs.append(value); ys.append(0) }
        }
        if xs.isEmpty {
            xs = [payload["domain"]["min"].double, payload["domain"]["max"].double]
        }
        if ys.isEmpty { ys = [-1, 1] }
        // A scene with no curve still needs a vertical window; base it on the marks.
        if payload["parts"].array.isEmpty == false && ys.count <= 2 {
            ys = [0, Double(max(payload["parts"].array.count, 2))]
        }
        minX = xs.min() ?? -6; maxX = xs.max() ?? 6
        minY = ys.min() ?? -6; maxY = ys.max() ?? 6
        pad(0.06)
    }

    private mutating func pad(_ fraction: Double) {
        let dx = max(maxX - minX, 1e-6) * fraction
        let dy = max(maxY - minY, 1e-6) * fraction
        minX -= dx; maxX += dx; minY -= dy; maxY += dy
        if maxX - minX < 1e-6 { minX -= 1; maxX += 1 }
        if maxY - minY < 1e-6 { minY -= 1; maxY += 1 }
    }

    func screenX(_ value: Double, _ area: CGRect) -> Double {
        area.minX + (value - minX) / (maxX - minX) * area.width
    }

    func screenY(_ value: Double, _ area: CGRect) -> Double {
        area.maxY - (value - minY) / (maxY - minY) * area.height
    }
}

extension JSON {
    /// Numbers only: a missing key or an explicit null means "no value here", which is
    /// different from zero. The plot needs that distinction to leave gaps.
    var optionalDouble: Double? {
        if case .number(let value) = self { return value }
        return nil
    }
}
